module rtl_checker #(
    parameter integer W = 2,
    parameter integer DEPTH = 4
) (
    input logic clk,
    input logic rst,
    input logic wr_en,
    input logic [W-1:0] din,
    input logic rd_en,
    input logic [W-1:0] dout,
    input logic full,
    input logic empty,
    input logic [$clog2(DEPTH):0] count
);
    // Reference model state (updated from inputs at each rising edge).
    logic valid = 1'b0;            // model established by a reset edge
    logic [W-1:0] q [0:DEPTH-1];   // retained words, q[0] is oldest
    integer mc;                    // model occupancy after previous edge
    logic lok;                     // previous edge was a successful read
    logic [W-1:0] ldata;           // word removed by previous edge
    logic [W-1:0] head;
    logic wacc;
    logic racc;
    integer i;

    // Sampled at each rising edge: outputs reflect state after previous edge.
    // Checks use the model state from previous edges, then the model is
    // advanced using the inputs present at this edge.
    always @(posedge clk) begin
        // Check observed outputs against the model (state after previous edge).
        if (valid) begin
            assert (count == mc);
            assert (empty == (mc == 0));
            assert (full == (mc == DEPTH));
            if (lok) begin
                assert (dout == ldata);
            end
        end

        // Advance the reference model with this edge's inputs.
        if (rst) begin
            valid = 1'b1;
            mc = 0;
            lok = 1'b0;
            ldata = '0;
        end else if (valid) begin
            wacc = wr_en && (mc != DEPTH);
            racc = rd_en && (mc != 0);

            if (racc) begin
                head = q[0];
                for (i = 0; i < DEPTH - 1; i = i + 1) begin
                    q[i] = q[i+1];
                end
                mc = mc - 1;
                ldata = head;
            end
            lok = racc;

            if (wacc) begin
                q[mc] = din;
                mc = mc + 1;
            end
        end
    end
endmodule

module rtl_checker #(
    parameter integer W = 2,
    parameter integer DEPTH = 4
) (
    input logic clk,
    input logic rst,
    input logic wr_en,
    input logic [W-1:0] din,
    input logic rd_en,
    input logic [W-1:0] dout,
    input logic full,
    input logic empty,
    input logic [$clog2(DEPTH):0] count
);
    // Reference model state, updated from inputs at each rising edge.
    // Outputs observed at a posedge reflect the result of the previous edge.
    reg                       init;     // model valid after first reset edge
    reg [$clog2(DEPTH):0]     mcount;   // retained words per model
    reg [W-1:0]               mem [0:DEPTH-1];
    reg                       rd_prev;  // successful read on previous edge
    reg [W-1:0]               exp_dout; // word removed by that read
    reg                       rd_ok;
    reg                       wr_ok;
    integer                   i;

    initial begin
        init     = 1'b0;
        mcount   = '0;
        rd_prev  = 1'b0;
        exp_dout = '0;
        rd_ok    = 1'b0;
        wr_ok    = 1'b0;
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem[i] = '0;
        end
    end

    always @(posedge clk) begin
        // Check outputs produced by the previous edge against the model.
        if (init) begin
            assert (count == mcount);
            assert (empty == (mcount == 0));
            assert (full == (mcount == DEPTH));
            if (rd_prev) begin
                assert (dout == exp_dout);
            end
        end

        // Advance the model using the inputs sampled at this edge.
        if (rst) begin
            init    = 1'b1;
            mcount  = '0;
            rd_prev = 1'b0;
        end
        else if (init) begin
            // Decisions use occupancy before this edge.
            rd_ok = rd_en && (mcount != 0);
            wr_ok = wr_en && (mcount != DEPTH);

            if (rd_ok) begin
                exp_dout = mem[0];
                for (i = 0; i < DEPTH - 1; i = i + 1) begin
                    mem[i] = mem[i + 1];
                end
                mcount = mcount - 1;
            end

            if (wr_ok) begin
                mem[mcount] = din;
                mcount = mcount + 1;
            end

            rd_prev = rd_ok;
        end
    end

endmodule

module rtl_checker (
    input logic [15:0] x,
    input logic [4:0] count
);
    // Reference population count: sums each bit of v (0..16 fits in 5 bits).
    function automatic logic [4:0] popcount16(input logic [15:0] v);
        logic [4:0] n;
        n = 5'd0;
        for (int i = 0; i < 16; i++) begin
            n = n + {4'd0, v[i]};
        end
        return n;
    endfunction

    // Combinational check: count must equal the number of set bits in x.
    always_comb begin
        assert (count == popcount16(x));
    end
endmodule

module rtl_checker (
    input logic [15:0] x,
    input logic [4:0] count
);
    // Reference population count of a 16-bit vector.
    function automatic logic [4:0] ref_popcount16(input logic [15:0] v);
        logic [4:0] c;
        integer i;
        begin
            c = 5'd0;
            for (i = 0; i < 16; i = i + 1) begin
                c = c + {4'd0, v[i]};
            end
            ref_popcount16 = c;
        end
    endfunction

    always_comb begin
        // count must equal the number of set bits in x
        assert (count == ref_popcount16(x));
        // the numerical output range is 0 through 16
        assert (count <= 5'd16);
    end
endmodule

module rtl_checker (
    input logic clk,
    input logic rst,
    input logic [3:0] req,
    input logic [3:0] gnt
);
    // Monitor state (model of the registered round-robin arbiter)
    logic started = 1'b0;          // becomes 1 after first reset edge
    logic [3:0] exp_gnt = 4'b0;    // expected registered grant
    logic [1:0] cursor = 2'd0;     // expected priority cursor

    integer k;
    integer idx;
    integer w;
    logic found;

    always @(posedge clk) begin
        // Check registered outputs produced by the previous edge
        if (started) begin
            assert (gnt == exp_gnt);
        end

        // Compute expected state produced by this edge
        if (rst) begin
            exp_gnt = 4'b0;
            cursor  = 2'd0;
            started = 1'b1;
        end
        else if (req == 4'b0) begin
            exp_gnt = 4'b0;
            // cursor preserved
        end
        else begin
            found = 1'b0;
            w = 0;
            for (k = 0; k < 4; k = k + 1) begin
                idx = (cursor + k) % 4;
                if (!found && req[idx]) begin
                    found = 1'b1;
                    w = idx;
                end
            end
            exp_gnt = 4'b1 << w;
            cursor  = 2'((w + 1) % 4);
        end
    end
endmodule

module rtl_checker (
    input logic clk,
    input logic rst,
    input logic [3:0] req,
    input logic [3:0] gnt
);
    // Monitor state, updated only at clock edges.
    logic     started = 1'b0;   // set once the first reset edge has occurred
    integer   cur     = 0;      // model of the priority cursor
    logic [3:0] exp_gnt = 4'b0; // model of the registered grant

    integer i;
    integer idx;
    integer w;
    integer ncur;
    logic [3:0] nx;

    always @(posedge clk) begin
        // Observed gnt is the state produced by the previous edge.
        if (started) begin
            assert (gnt == exp_gnt);
            // gnt must never be multi-hot or outside request
            assert ($countones(gnt) <= 1);
        end

        if (rst) begin
            started <= 1'b1;
            cur     <= 0;
            exp_gnt <= 4'b0;
        end else if (started) begin
            // Find first asserted request in cyclic order from cursor.
            w = -1;
            for (i = 0; i < 4; i = i + 1) begin
                idx = (cur + i) % 4;
                if (w < 0 && req[idx]) w = idx;
            end

            if (w < 0) begin
                nx   = 4'b0;
                ncur = cur;          // cursor preserved when no request
            end else begin
                nx   = 4'b1 << w;
                ncur = (w + 1) % 4;  // advance past the winner
            end

            exp_gnt <= nx;
            cur     <= ncur;
        end
    end
endmodule
